601	function summarizeSecretForLog(
602	  value: unknown
603	): { present: true; length: number; sha256Prefix: string } | null {
604	  const trimmed = nonEmptyTrimmedString(value);
605	  if (!trimmed) return null;
606	  return {
607	    present: true,
608	    length: trimmed.length,
609	    sha256Prefix: hashToken(trimmed).slice(0, 12)
610	  };
611	}
