613	function summarizeOpenClawGatewayDefaultsForLog(defaultsPayload: unknown) {
614	  const defaults = isPlainObject(defaultsPayload)
615	    ? (defaultsPayload as Record<string, unknown>)
616	    : null;
617	  const headers = defaults ? normalizeHeaderMap(defaults.headers) : undefined;
618	  const gatewayTokenValue = headers
619	    ? headerMapGetIgnoreCase(headers, "x-openclaw-token") ??
620	      headerMapGetIgnoreCase(headers, "x-openclaw-auth") ??
621	      tokenFromAuthorizationHeader(
622	        headerMapGetIgnoreCase(headers, "authorization")
623	      )
624	    : null;
625	  return {
626	    present: Boolean(defaults),
627	    keys: defaults ? Object.keys(defaults).sort() : [],
628	    url: defaults ? nonEmptyTrimmedString(defaults.url) : null,
629	    paperclipApiUrl: defaults
630	      ? nonEmptyTrimmedString(defaults.paperclipApiUrl)
631	      : null,
632	    headerKeys: headers ? Object.keys(headers).sort() : [],
633	    sessionKeyStrategy: defaults
634	      ? nonEmptyTrimmedString(defaults.sessionKeyStrategy)
635	      : null,
636	    disableDeviceAuth: defaults
637	      ? parseBooleanLike(defaults.disableDeviceAuth)
638	      : null,
639	    waitTimeoutMs:
640	      defaults && typeof defaults.waitTimeoutMs === "number"
641	        ? defaults.waitTimeoutMs
642	        : null,
643	    devicePrivateKeyPem: defaults
644	      ? summarizeSecretForLog(defaults.devicePrivateKeyPem)
645	      : null,
646	    gatewayToken: summarizeSecretForLog(gatewayTokenValue)
647	  };
648	}
