650	export function normalizeAgentDefaultsForJoin(input: {
651	  adapterType: string | null;
652	  defaultsPayload: unknown;
653	  deploymentMode: DeploymentMode;
654	  deploymentExposure: DeploymentExposure;
655	  bindHost: string;
656	  allowedHostnames: string[];
657	}) {
658	  const fatalErrors: string[] = [];
659	  const diagnostics: JoinDiagnostic[] = [];
660	  if (input.adapterType !== "openclaw_gateway") {
661	    const normalized = isPlainObject(input.defaultsPayload)
662	      ? (input.defaultsPayload as Record<string, unknown>)
663	      : null;
664	    return { normalized, diagnostics, fatalErrors };
665	  }
666	
667	  if (!isPlainObject(input.defaultsPayload)) {
668	    diagnostics.push({
669	      code: "openclaw_gateway_defaults_missing",
670	      level: "warn",
671	      message:
672	        "No OpenClaw gateway config was provided in agentDefaultsPayload.",
673	      hint:
674	        "Include agentDefaultsPayload.url and headers.x-openclaw-token for OpenClaw gateway joins."
675	    });
676	    fatalErrors.push(
677	      "agentDefaultsPayload is required for adapterType=openclaw_gateway"
678	    );
679	    return {
680	      normalized: null as Record<string, unknown> | null,
681	      diagnostics,
682	      fatalErrors
683	    };
684	  }
685	
686	  const defaults = input.defaultsPayload as Record<string, unknown>;
687	  const normalized: Record<string, unknown> = {};
688	
689	  let gatewayUrl: URL | null = null;
690	  const rawGatewayUrl = nonEmptyTrimmedString(defaults.url);
691	  if (!rawGatewayUrl) {
692	    diagnostics.push({
693	      code: "openclaw_gateway_url_missing",
694	      level: "warn",
695	      message: "OpenClaw gateway URL is missing.",
696	      hint: "Set agentDefaultsPayload.url to ws:// or wss:// gateway URL."
697	    });
698	    fatalErrors.push("agentDefaultsPayload.url is required");
699	  } else {
700	    try {
701	      gatewayUrl = new URL(rawGatewayUrl);
702	      if (gatewayUrl.protocol !== "ws:" && gatewayUrl.protocol !== "wss:") {
703	        diagnostics.push({
704	          code: "openclaw_gateway_url_protocol",
705	          level: "warn",
706	          message: `OpenClaw gateway URL must use ws:// or wss:// (got ${gatewayUrl.protocol}).`
707	        });
708	        fatalErrors.push(
709	          "agentDefaultsPayload.url must use ws:// or wss:// for openclaw_gateway"
710	        );
711	      } else {
712	        normalized.url = gatewayUrl.toString();
713	        diagnostics.push({
714	          code: "openclaw_gateway_url_configured",
715	          level: "info",
716	          message: `Gateway endpoint set to ${gatewayUrl.toString()}`
717	        });
718	      }
719	    } catch {
720	      diagnostics.push({
721	        code: "openclaw_gateway_url_invalid",
722	        level: "warn",
723	        message: `Invalid OpenClaw gateway URL: ${rawGatewayUrl}`
724	      });
725	      fatalErrors.push("agentDefaultsPayload.url is not a valid URL");
726	    }
727	  }
728	
729	  const headers = normalizeHeaderMap(defaults.headers) ?? {};
730	  const gatewayToken =
731	    headerMapGetIgnoreCase(headers, "x-openclaw-token") ??
732	    headerMapGetIgnoreCase(headers, "x-openclaw-auth") ??
733	    tokenFromAuthorizationHeader(headerMapGetIgnoreCase(headers, "authorization"));
734	  if (gatewayToken && !headerMapHasKeyIgnoreCase(headers, "x-openclaw-token")) {
735	    headers["x-openclaw-token"] = gatewayToken;
736	  }
737	  if (Object.keys(headers).length > 0) {
738	    normalized.headers = headers;
739	  }
740	
741	  if (!gatewayToken) {
742	    diagnostics.push({
743	      code: "openclaw_gateway_auth_header_missing",
744	      level: "warn",
745	      message: "Gateway auth token is missing from agent defaults.",
746	      hint:
747	        "Set agentDefaultsPayload.headers.x-openclaw-token (or legacy x-openclaw-auth)."
748	    });
749	    fatalErrors.push(
750	      "agentDefaultsPayload.headers.x-openclaw-token (or x-openclaw-auth) is required"
751	    );
752	  } else if (gatewayToken.trim().length < 16) {
753	    diagnostics.push({
754	      code: "openclaw_gateway_auth_header_too_short",
755	      level: "warn",
756	      message: `Gateway auth token appears too short (${gatewayToken.trim().length} chars).`,
757	      hint:
758	        "Use the full gateway auth token from ~/.openclaw/openclaw.json (typically long random string)."
759	    });
760	    fatalErrors.push(
761	      "agentDefaultsPayload.headers.x-openclaw-token is too short; expected a full gateway token"
762	    );
763	  } else {
764	    diagnostics.push({
765	      code: "openclaw_gateway_auth_header_configured",
766	      level: "info",
767	      message: "Gateway auth token configured."
768	    });
769	  }
770	
771	  if (isPlainObject(defaults.payloadTemplate)) {
772	    normalized.payloadTemplate = defaults.payloadTemplate;
773	  }
774	
775	  const parsedDisableDeviceAuth = parseBooleanLike(defaults.disableDeviceAuth);
776	  const disableDeviceAuth = parsedDisableDeviceAuth === true;
777	  if (parsedDisableDeviceAuth !== null) {
778	    normalized.disableDeviceAuth = parsedDisableDeviceAuth;
779	  }
780	
781	  const configuredDevicePrivateKeyPem = nonEmptyTrimmedString(
782	    defaults.devicePrivateKeyPem
783	  );
784	  if (configuredDevicePrivateKeyPem) {
785	    normalized.devicePrivateKeyPem = configuredDevicePrivateKeyPem;
786	    diagnostics.push({
787	      code: "openclaw_gateway_device_key_configured",
788	      level: "info",
789	      message:
790	        "Gateway device key configured. Pairing approvals should persist for this agent."
791	    });
792	  } else if (!disableDeviceAuth) {
793	    try {
794	      normalized.devicePrivateKeyPem = generateEd25519PrivateKeyPem();
795	      diagnostics.push({
796	        code: "openclaw_gateway_device_key_generated",
797	        level: "info",
798	        message:
799	          "Generated persistent gateway device key for this join. Pairing approvals should persist for this agent."
